@startuml

class SmartHome {
  + physicalAddress : string
}

class Room {}

class SensorDevice {
  + deviceIdentifier : string
}

class ActuatorDevice {
  + deviceIdentifier : string
}

class SensorReading {
  + value : double
  + timestamp : time
}

class ControlCommand {
  + commandName : string
  + timestamp : time
  + status : string
}

class ActivityLog {}

class User {
  + name : string
}

class AutomationRule {
  + precondition : string
  + action : string
  + ruleStatus : string
  + triggerTimestamp : time
}

SmartHome "1" *-- "*" Room
Room "1" -- "*" SensorDevice
Room "1" -- "*" ActuatorDevice
SensorDevice "1" -- "*" SensorReading
ActuatorDevice "1" -- "*" ControlCommand
SmartHome "1" *-- "*" SensorReading
SmartHome "1" *-- "*" ControlCommand
SmartHome "1" *-- "*" ActivityLog
User "1" -- "*" AutomationRule : manages
AutomationRule "0..*" -- "0..*" AutomationRule : depends on / conflicts with

@enduml

